import type { DocumentCopy } from '@/components/app-document-page'

export const userGuide: { en: DocumentCopy; ar: DocumentCopy } = {
  en: {
    title: 'Fleet Manager user guide',
    subtitle: 'Step-by-step help for fleet, workshop, tire, oil-change, reporting, account, and Excel-sync tasks. The pages you can open depend on your account permissions.',
    updatedLabel: 'Last updated',
    contentsLabel: 'On this page',
    sections: [
      { id: 'getting-started', title: 'Getting started', paragraphs: ['Sign in at /login. New accounts may need email verification and administrator approval before the system grants access. If you cannot sign in, use the password reset link or contact your administrator.'], bullets: ['Use the sidebar to open a page. On a phone, use the menu button to open navigation.', 'Use the language control to switch English or Arabic, and the theme control to change appearance.', 'Pages hidden from your menu are unavailable to your account. Ask an administrator to review your role and individual permissions.'] },
      { id: 'dashboard', title: 'Dashboard', paragraphs: ['The dashboard summarizes fleet records, maintenance, and activity available to your account. Use its cards and links to move into the relevant list and inspect the underlying records. Dashboard counts depend on the data currently recorded in the system.'] },
      { id: 'trucks', title: 'Trucks', paragraphs: ['Open Trucks to search and view the truck register. A truck record can contain its plate, VIN, make, model, year, mileage, driver, status, oil-change dates, and other fleet details.'], bullets: ['Use Add, Edit, or Delete only when those actions are enabled for your account.', 'Update driver and mileage details on the truck record so dashboards, maintenance checks, and Excel exports use the current values.', 'Review a truck’s linked maintenance and job-card history before changing or retiring its record.'] },
      { id: 'trailers', title: 'Trailers', paragraphs: ['Open Trailers to manage trailer numbers, status, driver, inspection dates, and maintenance history. Use the trailer number consistently when creating a job card or recording trailer-related work.'] },
      { id: 'document-expiry', title: 'Document expiry tracker and protection cards', paragraphs: ['Use Document Expiry Tracker for each truck’s fire extinguisher, operation card, Istimara, insurance, driver card, and Fahas records. Set an expiry date; the reminder starts automatically 10 days earlier. No file is needed for Fire Extinguisher. Upload a file for the other five document types. The tracker shows missing, current, reminder-started, and expired entries.'], bullets: ['Each truck keeps one current file per expiry document type that requires an upload. Uploading that same type again replaces its previous file.', 'For a truck or trailer Protection Card, open the vehicle details on its existing page. Each vehicle has its own private file, with no expiry date or reminder. Uploading again replaces that vehicle’s current file.', 'Job cards remain the maintenance records and drive maintenance tracking.'] },
      { id: 'tires', title: 'Tire management', paragraphs: ['Tire Management records tire issue/out entries, including size, out quantity, driver, truck or trailer association, serial number, manufacturer/origin, date, and notes when those fields are available. Use the tire-entry form as the source for new tire records.'], bullets: ['Search and filter the table by the available tire, vehicle, driver, serial, and date fields.', 'The tire analytics and reports count positive Out Qty values. A zero quantity does not add to the tire total; keep a zero-quantity historical row only when it is meaningful to the record.', 'Check the source row and quantity before saving imports. Workbook-origin and manufacturer values must use accepted values shown by the form or validation message.'] },
      { id: 'job-cards', title: 'Workshop job cards', paragraphs: ['Workshop Job Cards is the system’s work-order page for truck and trailer workshop jobs. The older Maintenance route redirects here. Create a card for the vehicle, then record the service date/type, reported issue, priority, odometer when relevant, technician, driver, work performed, parts, checklist, notes, and next-service schedule.'], bullets: ['Save the card, then use its preview, download, or print action to create the job-card document. The document is formatted as a single-page A4 portrait form.', 'A share link opens a read-only copy of that job card for anyone who has the link. Share it only with intended recipients; the card may contain vehicle, driver, work, and signature details.', 'Job-card maintenance schedules can feed due/overdue notifications and the Excel workbook when those integrations are configured.'] },
      { id: 'oil-changes', title: 'Oil changes', paragraphs: ['Use Oil Changes to record and review oil-change events separately from general workshop cards. Select the truck and enter the actual date, mileage, driver, and oil details available on the form. Accurate dates and odometers are needed for useful maintenance history and reporting.'] },
      { id: 'purchase-invoices', title: 'Purchase invoices and fleet accounts', paragraphs: ['Use Purchase Invoices & Accounts to enter vendor bills for maintenance, spare parts, tires, batteries, oil and filters, and other fleet expenses. Add the vendor, invoice number and dates, then add one or more lines and search for the truck or trailer responsible for each cost.'], bullets: ['Choose VAT invoice or No VAT. For a VAT invoice, use the rate shown on the supplier invoice (15% is the starting rate) and indicate whether prices include VAT.', 'Posting debits the assigned truck/trailer expense account, records input VAT separately when applicable, and credits the vendor payable account for the full bill. No-VAT bills post no input VAT.', 'Use Truck & Trailer Accounts, Vendor Accounts, and Input VAT to inspect ledger history. Payments and bank reconciliation are not recorded here.', 'Posted invoices are locked. Authorized users can reverse an incorrect bill; the system keeps the original and records a counter-entry for audit.'] },
      { id: 'spare-parts', title: 'Spare parts and consumables inventory', paragraphs: ['Open Spare Parts & Consumables to manage workshop stock such as engine oil, oil filters, diesel filters, air filters, fuel filters, and general parts. Create each stock item once, then record every receipt, issue, return, and adjustment so the balance and transaction history remain traceable.'], bullets: ['When creating an item, enter its name, optional part number, category, unit (pcs, litre, kg, set, or box), optional oil grade, and reorder level. Choose the unit that matches how the item is actually counted; quantities and reorder levels use that same unit.', 'Use Purchase / stock in when goods arrive, Issue to vehicle when stock is used, Customer return or Supplier return for returned goods, and the appropriate adjustment when correcting a physical count. Add the date, quantity, reference or job-card number, vehicle details for issues, and notes where relevant.', 'The Current stock tab shows the calculated balance, unit, reorder threshold, and reorder status. Use Edit stock to reconcile the balance with a verified physical count; the adjustment is recorded in the ledger. Use Edit reorder to change the low-stock threshold.', 'Use Transaction history to trace movements. A low/reorder status means the current balance is at or below the item’s reorder level. It is an inventory indicator, separate from the maintenance notification system.'] },
      { id: 'mechanics', title: 'Mechanics', paragraphs: ['Mechanics is the technician directory. Add or update mechanic contact and specialty information where your permissions allow, then select the mechanic or technician on applicable maintenance records and job cards.'] },
      { id: 'reports', title: 'Reports and analytics', paragraphs: ['Reports generate filtered views of the records available in the system. Set the date range and filters, choose one vehicle or several when the report supports selection, review the preview, then download the report. A single selected truck, trailer, or tire filter should produce a report for that selection; multiple selections include each selected record.'], bullets: ['Use the preview and matching-record count to confirm the scope before downloading.', 'Advanced Analytics shows aggregated trends; it is not a substitute for reviewing the source records.', 'If the report is empty, clear restrictive filters and verify that matching records exist in the selected dates.'] },
      { id: 'notifications', title: 'Notifications', paragraphs: ['The bell in the top bar shows recent in-app notifications. Open Notifications for the full list, refresh, filter unread items, and mark notifications as read. The header refreshes its list about every 30 seconds while the app is open.'], bullets: ['Maintenance checks run from the production scheduled job once each day, targeting 04:00 UTC (07:00 in Riyadh); hosting schedules can introduce a delay.', 'Checks use upcoming and overdue maintenance dates, truck mileage intervals, trailer inspection/maintenance dates, and job-card next-service dates or mileage.', 'Email notifications require the email option to be enabled and the email provider to be configured. Maintenance alert email delivery is to active, approved administrators.', 'Low-stock alerts are not available because spare-parts inventory quantities are not stored in the application.'] },
      { id: 'excel-sync', title: 'OneDrive Excel Sync and Excel Changes', paragraphs: ['Excel Sync connects an administrator-authorized personal Microsoft OneDrive account. The workbook contains fleet, trailer, maintenance, oil-change, tire, and workshop job-card data. App changes trigger workbook refreshes when the integration is connected; administrators can also use Sync Now.'], bullets: ['Edits or additions made in the workbook are detected and shown in Excel Changes for review. They are not silently written into the app.', 'Apply a change or use the bulk action for eligible changes. The server checks the applying user’s current role and permissions and validates the row before saving it.', 'Conflicts, invalid values, and changes your role cannot apply need individual review. A deleted worksheet row does not delete an app record.', 'Use the workbook link and Last successful update in Settings → Excel Sync to check the connected file and sync status.'] },
      { id: 'profile-users', title: 'Profile and user accounts', paragraphs: ['Profile shows your account information and lets you update profile fields or photo where permitted. User Management is for authorized administrators and managers: create or update accounts, approve or reactivate them, and assign roles or individual permissions.'], bullets: ['Role permissions control which sections and operations are available. User-specific overrides can further restrict or grant allowed access.', 'Do not share passwords or one-time codes. Ask an administrator to disable access when a staff member should no longer use the app.'] },
      { id: 'settings', title: 'Settings and system administration', paragraphs: ['Settings contains the configuration available to your role, such as company details used on documents, currency and time zone, maintenance intervals, notifications, system preferences, OneDrive Excel Sync, and role permissions. Some tabs and actions are administrator-only.'], bullets: ['Save settings after editing and check for a success message.', 'Admin pages provide user activity, system monitoring, and administration actions. Treat backup files and exported logs as sensitive business data.'] },
      { id: 'organizations', title: 'Organizations and workspaces', paragraphs: ['The application supports separate organization workspaces. Each workspace has its own organization context and data boundary; users should work only in the workspace assigned to their company. Organization creation, provisioning, payment-request review, and workspace administration are restricted to the primary administrator.'], bullets: ['Confirm the organization/workspace shown at sign-in before entering or importing records.', 'A new workspace is not active merely because a purchase request was submitted. For bank-transfer setup, access and database provisioning begin only after the administrator confirms receipt of the transfer.', 'Do not copy business records between organizations unless authorized. Contact the primary administrator if the wrong workspace or organization data appears.'] },
      { id: 'troubleshooting', title: 'Troubleshooting and support', paragraphs: ['If a page or action is missing, first check the current account and role. If a workbook is stale, check its connected status and last successful update, then use Sync Now or ask an administrator to reconnect OneDrive. For a workbook edit, open Excel Changes and review validation or conflict details.'], bullets: ['If email alerts fail, ask an administrator to check the email setting, sender configuration, and deployment logs.', 'For incorrect records, capture the record number, page, date, and a brief description; do not send passwords, access tokens, or secret keys.', 'Contact the fleet system administrator or alaminkhan.xiaomi@gmail.com for account and application support.'] },
    ],
  },
  ar: {
    title: 'دليل مستخدم مدير الأسطول',
    subtitle: 'إرشادات خطوة بخطوة لإدارة الأسطول والورشة والإطارات وتغيير الزيت والتقارير والحساب ومزامنة Excel. تعتمد الصفحات المتاحة على صلاحيات حسابك.',
    updatedLabel: 'آخر تحديث',
    contentsLabel: 'في هذه الصفحة',
    sections: [
      { id: 'getting-started', title: 'البدء', paragraphs: ['سجّل الدخول من /login. قد تحتاج الحسابات الجديدة إلى التحقق من البريد الإلكتروني وموافقة المسؤول قبل منحها حق الوصول. إذا تعذر تسجيل الدخول، استخدم رابط إعادة تعيين كلمة المرور أو تواصل مع المسؤول.'], bullets: ['استخدم الشريط الجانبي لفتح الصفحات. على الهاتف، افتح قائمة التنقل من زر القائمة.', 'استخدم مفتاح اللغة للتبديل بين العربية والإنجليزية، ومفتاح المظهر لتغيير شكل التطبيق.', 'الصفحات غير الظاهرة في القائمة غير متاحة لحسابك. اطلب من المسؤول مراجعة دورك وصلاحياتك الفردية.'] },
      { id: 'dashboard', title: 'لوحة التحكم', paragraphs: ['تلخص لوحة التحكم سجلات الأسطول والصيانة والنشاط المتاح لحسابك. استخدم البطاقات والروابط للانتقال إلى القوائم ومراجعة السجلات الأصلية. تعتمد الأعداد على البيانات المسجلة حالياً في النظام.'] },
      { id: 'trucks', title: 'الشاحنات', paragraphs: ['افتح الشاحنات للبحث في سجل الشاحنات وعرضه. قد يتضمن سجل الشاحنة رقم اللوحة ورقم الهيكل والشركة والطراز والسنة والعداد والسائق والحالة وتواريخ تغيير الزيت وبيانات أخرى.'], bullets: ['استخدم الإضافة أو التعديل أو الحذف فقط إذا كانت الصلاحية متاحة لحسابك.', 'حدّث بيانات السائق والعداد في سجل الشاحنة كي تستخدم لوحة التحكم وفحوص الصيانة وتصدير Excel القيم الحالية.', 'راجع سجلات الصيانة وأوامر العمل المرتبطة قبل تعديل السجل أو إيقافه.'] },
      { id: 'trailers', title: 'المقطورات', paragraphs: ['افتح المقطورات لإدارة أرقام المقطورات والحالة والسائق وتواريخ الفحص وسجل الصيانة. استخدم رقم المقطورة نفسه باستمرار عند إنشاء أمر عمل أو تسجيل عمل خاص بها.'] },
      { id: 'document-expiry', title: 'متابعة صلاحية المستندات وبطاقة الحماية', paragraphs: ['استخدم صفحة متابعة صلاحية المستندات لتسجيل بيانات طفاية الحريق وبطاقة التشغيل والاستمارة والتأمين وبطاقة السائق والفحص الفني لكل شاحنة. أدخل تاريخ الانتهاء؛ يبدأ التذكير تلقائياً قبل 10 أيام. لا يلزم رفع ملف لبيانات طفاية الحريق، بينما يلزم رفع ملف للأنواع الخمسة الأخرى. تعرض الصفحة المستندات الناقصة والسارية والتي بدأ تذكيرها والمنتهية.'], bullets: ['تحتفظ كل شاحنة بملف حالي واحد لكل نوع من المستندات التي تتطلب ملفاً. يؤدي رفع النوع نفسه مرة أخرى إلى استبدال الملف السابق.', 'لرفع بطاقة حماية الشاحنة أو المقطورة، افتح تفاصيلها من صفحتها الحالية. لكل مركبة ملف خاص لا يتطلب تاريخ صلاحية أو تذكير. يؤدي الرفع مرة أخرى إلى استبدال بطاقة الحماية الحالية.', 'تظل أوامر العمل سجلات الصيانة وهي التي تغذي متابعة الصيانة.'] },
      { id: 'tires', title: 'إدارة الإطارات', paragraphs: ['تسجل إدارة الإطارات حركات إخراج الإطارات، ومنها المقاس والكمية الخارجة والسائق وربط الشاحنة أو المقطورة والرقم التسلسلي والمنشأ أو الشركة المصنعة والتاريخ والملاحظات عند توفر الحقول. استخدم نموذج الإطارات لإضافة السجلات الجديدة.'], bullets: ['ابحث وصفِّ الجدول باستخدام الحقول المتاحة للمقاس والمركبة والسائق والرقم التسلسلي والتاريخ.', 'تحسب التحليلات والتقارير الكميات الخارجة الموجبة فقط. لا تزيد الكمية الصفرية إجمالي الإطارات؛ احتفظ بسجل صفري فقط عندما تكون له قيمة في التاريخ.', 'تحقق من صف المصدر والكمية قبل حفظ الاستيراد. يجب أن تستخدم قيم المنشأ والشركة المصنعة القيم المقبولة في النموذج أو رسالة التحقق.'] },
      { id: 'job-cards', title: 'أوامر عمل الورشة', paragraphs: ['أوامر عمل الورشة هي صفحة أوامر الصيانة للشاحنات والمقطورات. يحوّل مسار الصيانة القديم إلى هذه الصفحة. أنشئ أمراً للمركبة ثم سجّل تاريخ ونوع الخدمة والشكوى والأولوية والعداد عند الحاجة والفني والسائق والأعمال المنفذة والقطع وقائمة الفحص والملاحظات وموعد الخدمة القادمة.'], bullets: ['بعد حفظ الأمر، استخدم المعاينة أو التنزيل أو الطباعة لإنشاء مستند أمر العمل. يُنسق المستند كنموذج A4 عمودي من صفحة واحدة.', 'يفتح رابط المشاركة نسخة للقراءة فقط من أمر العمل لكل من لديه الرابط. شاركه مع المستلمين المقصودين فقط؛ فقد يحتوي الأمر على بيانات المركبة والسائق والعمل والتوقيعات.', 'قد تدخل مواعيد الصيانة في أمر العمل ضمن تنبيهات الاستحقاق وملف Excel عند إعداد التكامل.'] },
      { id: 'oil-changes', title: 'تغييرات الزيت', paragraphs: ['استخدم صفحة تغييرات الزيت لتسجيل ومراجعة أحداث تغيير الزيت بصورة مستقلة عن أوامر الورشة العامة. اختر الشاحنة وأدخل التاريخ والعداد والسائق وبيانات الزيت المتاحة في النموذج. يلزم إدخال التاريخ والعداد بدقة للاستفادة من سجل الصيانة والتقارير.'] },
      { id: 'purchase-invoices', title: 'فواتير المشتريات وحسابات الأسطول', paragraphs: ['استخدم صفحة فواتير المشتريات والحسابات لتسجيل فواتير الموردين الخاصة بالصيانة وقطع الغيار والإطارات والبطاريات والزيت والفلاتر ومصاريف الأسطول الأخرى. أضف المورد ورقم الفاتورة وتواريخها، ثم أضف بنداً أو أكثر وابحث عن الشاحنة أو المقطورة التي تتحمل كل تكلفة.'], bullets: ['اختر فاتورة ضريبية أو بدون ضريبة. في الفاتورة الضريبية أدخل النسبة الموجودة في فاتورة المورد (النسبة الافتراضية 15٪) وحدد ما إذا كانت الأسعار تشمل الضريبة.', 'عند الترحيل يُحمّل حساب مصروف الشاحنة أو المقطورة المختارة، ويُسجل ضريبة المدخلات في حساب منفصل عند انطباقها، ويُقيد كامل مبلغ الفاتورة في حساب مستحقات المورد.', 'استخدم حسابات الشاحنات والمقطورات وحسابات الموردين وضريبة المدخلات لمراجعة سجل القيود. لا تُسجل هذه الصفحة المدفوعات أو التسوية البنكية.', 'تُقفل الفواتير بعد ترحيلها. يستطيع المستخدم المخول عكس الفاتورة الخاطئة مع الاحتفاظ بالقيد الأصلي والقيد العكسي لأغراض المراجعة.'] },
      { id: 'spare-parts', title: 'مخزون قطع الغيار والمواد الاستهلاكية', paragraphs: ['افتح صفحة قطع الغيار والمواد الاستهلاكية لإدارة مخزون الورشة مثل زيت المحرك وفلاتر الزيت والديزل والهواء والوقود والقطع العامة. أنشئ كل صنف مرة واحدة، ثم سجّل كل عملية استلام وصرف وإرجاع وتسوية حتى يبقى الرصيد وسجل الحركات قابلين للتتبع.'], bullets: ['عند إنشاء الصنف، أدخل الاسم ورقم القطعة الاختياري والفئة ووحدة القياس (قطعة أو لتر أو كجم أو طقم أو صندوق) ودرجة الزيت الاختيارية وحد إعادة الطلب. اختر الوحدة التي تُحسب بها المادة فعلياً؛ وتستخدم الكمية وحد إعادة الطلب الوحدة نفسها.', 'استخدم شراء / إدخال مخزون عند استلام البضاعة، وصرف إلى مركبة عند الاستخدام، وإرجاع من عميل أو إرجاع إلى مورد عند الإرجاع، والتسوية المناسبة لتصحيح الجرد الفعلي. أضف التاريخ والكمية والمرجع أو رقم أمر العمل وبيانات المركبة عند الصرف والملاحظات عند الحاجة.', 'تعرض علامة المخزون الحالي الرصيد المحسوب والوحدة وحد إعادة الطلب والحالة. استخدم تعديل المخزون لمطابقة الرصيد مع جرد فعلي تم التحقق منه؛ وتسجل العملية كتسوية في سجل الحركات. استخدم تعديل حد إعادة الطلب لتغيير الحد الأدنى.', 'استخدم سجل الحركات لتتبع كل حركة. تعني حالة إعادة الطلب أن الرصيد الحالي يساوي حد إعادة الطلب أو يقل عنه. وهذا مؤشر للمخزون مستقل عن إشعارات الصيانة.'] },
      { id: 'mechanics', title: 'الفنيون', paragraphs: ['صفحة الفنيين هي دليل العاملين في الصيانة. أضف أو حدّث بيانات الاتصال والتخصص عند توفر الصلاحية، ثم اختر الفني في سجلات الصيانة وأوامر العمل ذات الصلة.'] },
      { id: 'reports', title: 'التقارير والتحليلات', paragraphs: ['تنشئ صفحة التقارير نتائج مفلترة من السجلات المتاحة في النظام. حدد النطاق الزمني والفلاتر، واختر مركبة واحدة أو عدة مركبات عندما يدعم التقرير ذلك، ثم راجع المعاينة ونزّل التقرير. عند اختيار شاحنة أو مقطورة أو إطار واحد، يجب أن يقتصر التقرير على ذلك الاختيار؛ والاختيارات المتعددة تشمل كل السجلات المحددة.'], bullets: ['استخدم المعاينة وعدد السجلات المطابقة للتحقق من النطاق قبل التنزيل.', 'تعرض التحليلات المتقدمة الاتجاهات المجمعة، ولا تغني عن مراجعة السجلات الأصلية.', 'إذا كان التقرير فارغاً، أزل الفلاتر المقيّدة وتحقق من وجود سجلات مطابقة ضمن التواريخ المحددة.'] },
      { id: 'notifications', title: 'الإشعارات', paragraphs: ['يعرض رمز الجرس في الشريط العلوي أحدث الإشعارات داخل التطبيق. افتح صفحة الإشعارات لمراجعة القائمة كاملة وتحديثها وتصفية غير المقروء منها وتعليمها كمقروءة. يحدّث الشريط العلوي القائمة كل 30 ثانية تقريباً أثناء فتح التطبيق.'], bullets: ['تعمل فحوصات الصيانة من مهمة مجدولة في الإنتاج مرة يومياً، وتستهدف الساعة 04:00 بالتوقيت العالمي (07:00 في الرياض)؛ وقد يتأخر التنفيذ بحسب جدولة الاستضافة.', 'تفحص التواريخ ومواعيد الصيانة المتأخرة، وفترات عداد الشاحنات، وفحوص وصيانة المقطورات، وتاريخ أو عداد الخدمة التالية في أوامر العمل.', 'تتطلب رسائل البريد تفعيل خيار البريد وإعداد مزود البريد. تُرسل رسائل تنبيه الصيانة إلى المسؤولين النشطين والمعتمدين.', 'تنبيهات انخفاض المخزون غير متاحة لأن كميات مخزون قطع الغيار غير محفوظة في التطبيق.'] },
      { id: 'excel-sync', title: 'مزامنة OneDrive Excel وتغييرات Excel', paragraphs: ['تربط مزامنة Excel حساب OneDrive شخصياً وافق عليه المسؤول. يحتوي المصنف على بيانات الشاحنات والمقطورات والصيانة وتغييرات الزيت والإطارات وأوامر عمل الورشة. تؤدي تغييرات التطبيق إلى تحديث المصنف عند اتصال التكامل، ويمكن للمسؤول استخدام «مزامنة الآن».'], bullets: ['تظهر التعديلات أو الإضافات التي تتم في المصنف للمراجعة في صفحة تغييرات Excel، ولا تُحفظ في التطبيق تلقائياً.', 'طبّق التغيير أو استخدم الإجراء الجماعي للتغييرات المؤهلة. يتحقق الخادم من الدور والصلاحيات الحالية للمستخدم ومن صحة الصف قبل الحفظ.', 'تحتاج التعارضات والقيم غير الصالحة والتغييرات التي لا تسمح بها صلاحيتك إلى مراجعة. حذف صف من ورقة العمل لا يحذف سجل التطبيق.', 'راجع المصنف وآخر تحديث ناجح في الإعدادات ← مزامنة Excel للتحقق من الملف وحالة المزامنة.'] },
      { id: 'profile-users', title: 'الملف الشخصي وحسابات المستخدمين', paragraphs: ['تعرض صفحة الملف الشخصي بيانات حسابك وتتيح تعديل بيانات الملف أو صورته عند توفر الصلاحية. إدارة المستخدمين مخصصة للمسؤولين والمديرين المخولين: إنشاء الحسابات أو تحديثها والموافقة عليها أو إعادة تفعيلها وتحديد الأدوار أو الصلاحيات الفردية.'], bullets: ['تحدد صلاحيات الدور الأقسام والعمليات المتاحة. وقد تقيّد صلاحيات المستخدم الفردية الوصول أكثر أو تمنح صلاحية مسموحة.', 'لا تشارك كلمات المرور أو رموز الدخول لمرة واحدة. اطلب من المسؤول تعطيل الحساب عندما لا يعود الموظف بحاجة إلى التطبيق.'] },
      { id: 'settings', title: 'الإعدادات وإدارة النظام', paragraphs: ['تتضمن الإعدادات الخيارات المتاحة لدورك، مثل بيانات الشركة التي تظهر في المستندات والعملة والمنطقة الزمنية وفترات الصيانة والإشعارات وتفضيلات النظام ومزامنة OneDrive Excel وصلاحيات الأدوار. بعض علامات التبويب والإجراءات مخصصة للمسؤول.'], bullets: ['احفظ الإعدادات بعد تعديلها وتحقق من ظهور رسالة نجاح.', 'توفر صفحات المسؤول نشاط المستخدمين ومراقبة النظام وإجراءات الإدارة. تعامل مع النسخ الاحتياطية وسجلات التصدير كبيانات عمل حساسة.'] },
      { id: 'organizations', title: 'المؤسسات ومساحات العمل', paragraphs: ['يدعم التطبيق مساحات عمل منفصلة للمؤسسات. لكل مساحة عمل سياق مؤسسي وحدود بيانات خاصة بها؛ ويجب على المستخدم العمل داخل مساحة العمل المخصصة لشركته فقط. يقتصر إنشاء المؤسسات وتجهيز قواعد بياناتها ومراجعة طلبات الدفع وإدارة مساحات العمل على المسؤول الرئيسي.'], bullets: ['تحقق من المؤسسة أو مساحة العمل الظاهرة عند تسجيل الدخول قبل إدخال السجلات أو استيرادها.', 'لا تصبح مساحة العمل نشطة بمجرد إرسال طلب الشراء. في إعداد التحويل المصرفي، يبدأ الوصول وتجهيز قاعدة البيانات فقط بعد تأكيد المسؤول استلام التحويل.', 'لا تنسخ سجلات العمل بين المؤسسات إلا بتصريح. تواصل مع المسؤول الرئيسي إذا ظهرت مساحة عمل أو بيانات مؤسسة غير صحيحة.'] },
      { id: 'troubleshooting', title: 'استكشاف الأخطاء والدعم', paragraphs: ['إذا لم تظهر صفحة أو عملية، فتحقق أولاً من الحساب والدور الحاليين. إذا كان مصنف Excel قديماً، تحقق من الاتصال وآخر تحديث ناجح، ثم استخدم «مزامنة الآن» أو اطلب من المسؤول إعادة الاتصال بـ OneDrive. لتعديل في المصنف، افتح تغييرات Excel وراجع تفاصيل التحقق أو التعارض.'], bullets: ['إذا فشلت التنبيهات البريدية، اطلب من المسؤول التحقق من إعداد البريد والمرسل وسجلات النشر.', 'للإبلاغ عن سجل غير صحيح، أرسل رقم السجل والصفحة والتاريخ ووصفاً مختصراً؛ لا ترسل كلمات المرور أو رموز الوصول أو المفاتيح السرية.', 'تواصل مع مسؤول نظام الأسطول أو عبر alaminkhan.xiaomi@gmail.com للمساعدة في الحساب والتطبيق.'] },
    ],
  },
}

export const privacyPolicy: { en: DocumentCopy; ar: DocumentCopy } = {
  en: {
    title: 'Privacy Policy',
    subtitle: 'How Saadfreeh Transport Est. handles personal and operational information in Fleet Manager.',
    updatedLabel: 'Effective date',
    contentsLabel: 'Policy sections',
    sections: [
      { id: 'controller', title: 'Who operates the service', paragraphs: ['The service is operated for Saadfreeh Transport Est. (“the Company”, “we”, “us”). Company details shown in the app are managed in Settings. For privacy requests or questions, contact alaminkhan.xiaomi@gmail.com or the Company administrator.'] },
      { id: 'scope', title: 'Scope and applicability', paragraphs: ['This policy covers the Fleet Manager web application, its APIs, account access, operational records, reports, and connected Excel/OneDrive features. The Company acts as the controller for information it enters or manages in the service. Microsoft OneDrive, email, hosting, database, and analytics providers process information under their own terms as applicable.'] },
      { id: 'information', title: 'Information the application handles', bullets: ['Account details: name, email, password hash, phone, department, job title, biography, profile image, role, permissions, account approval and verification status, and account recovery/verification data.', 'Fleet, workshop, and purchasing records: truck and trailer identifiers, VINs, drivers, mileage, status, maintenance history, oil changes, tire issue quantities and serials, mechanics, job-card details, vendor names and contact details, invoice numbers and dates, expense categories, amounts, VAT and fleet/vendor ledger entries, notes, costs, attachments or signatures when supplied, and generated reports.', 'Organization purchase requests: organization and workspace names, administrator name and email, optional phone number, selected plan, requested amount, a unique bank-transfer reference, agreement acceptance time/version, review status, and administrator review details. Do not submit bank login credentials or payment card details; the app does not collect them.', 'Security and audit information: sign-in history, activity and audit entries, actions and record changes, IP address, user agent, browser, operating system, device type, and approximate location derived from IP when available.', 'Connected workbook information: Microsoft account email and an encrypted OneDrive refresh token, workbook identifiers/links, sync status, and staged Excel changes.', 'Usage and performance information: page and interaction telemetry from Vercel Analytics/Speed Insights and Microsoft Clarity. The current Clarity integration identifies signed-in sessions with the app user ID and sends the user role, email, and name as session metadata. There is currently no in-app analytics opt-out control.', 'Information you send to support, and delivery information needed for account verification, password recovery, and enabled notification emails.'] },
      { id: 'purposes', title: 'Why information is used', bullets: ['To create and secure accounts, authenticate users, apply role and user-specific permissions, approve access, and recover accounts.', 'To receive and review workspace purchase requests, match manually initiated bank transfers using their references, provision approved workspaces and administrator access, and maintain purchase and payment records.', 'To manage fleet assets, service history, job cards, tire and oil records, vendor invoices, vehicle expense accounts, input VAT, reports, and Excel synchronization requested by the Company.', 'To display in-app maintenance notifications, send configured operational emails, investigate errors, maintain audit trails, and support users.', 'To monitor application reliability, performance, and usage and to improve the service.'] },
      { id: 'sharing', title: 'When information is shared', paragraphs: ['Authorized app users can see and act on records according to their roles and individual permissions. Organization purchase request details are available to the primary organization administrator for payment review and workspace provisioning. Service providers receive information needed to host, operate, secure, analyze, or deliver the service: Vercel (hosting and telemetry), Neon (PostgreSQL database), Microsoft (OneDrive/Graph and Clarity), Resend (email), and ip-api.com (approximate IP-based location lookup used by activity tracking). The Company may also disclose information when required by law or to protect the service and its users. The application is not operated as a data brokerage.'] },
      { id: 'public-links', title: 'Job-card share links and exports', paragraphs: ['A job-card share link is a bearer link: anyone who obtains the link can view the shared job card without signing in. It may display the job number, truck or trailer details, VIN or plate, driver and technician names, work description, checklist, notes, and signatures saved on that card. Only share it with intended recipients. Downloaded PDFs, reports, and workbook exports can contain the same kinds of business or personal information; protect them when storing or forwarding.'] },
      { id: 'onedrive', title: 'OneDrive and workbook synchronization', paragraphs: ['When an administrator connects OneDrive, the user grants the app Microsoft Graph delegated access to the selected account’s files for the workbook integration. The app reads and writes the fleet workbook and stores the refresh token encrypted on the server. Workbook edits are staged for permission-checked review before changing app records; app data may be written back to the connected workbook. Microsoft account and workbook data are also subject to Microsoft’s terms and privacy information.'] },
      { id: 'transfers', title: 'Storage and international processing', paragraphs: ['Fleet Manager uses a PostgreSQL database and external cloud services. The current production database connection is configured for a US East region; service providers may process data in other locations depending on their infrastructure and the connected Microsoft account. Information may therefore be processed outside Saudi Arabia. The Company is responsible for applying the safeguards and transfer requirements that apply under Saudi Arabia’s Personal Data Protection Law and its transfer regulations.'] },
      { id: 'retention', title: 'Retention and deletion', paragraphs: ['The Company retains information while it is needed to operate accounts, maintain fleet and workshop history, meet business and legal obligations, protect the service, and resolve disputes. Some records are soft-deleted or retained in audit history, and backup copies may remain until the applicable backup cycle expires. The application does not publish one fixed retention period for every record type. Contact the Company to request review, correction, or deletion; statutory duties and operational record requirements may limit deletion.'] },
      { id: 'choices', title: 'Your choices and privacy requests', paragraphs: ['You can correct profile information available in your account and ask the Company to access, provide, correct, complete, update, or destroy personal data, or to address consent where consent is the applicable basis. Requests are handled subject to identity verification, applicable law, and its exceptions. Contact alaminkhan.xiaomi@gmail.com or the Company administrator and identify the account and request; do not include a password or access token.'] },
      { id: 'security', title: 'Security', paragraphs: ['The application uses authentication, role-based access checks, audit logging, and encrypted storage for the OneDrive refresh token. Passwords are stored as hashes. No internet service can guarantee absolute security. Keep credentials private, use only authorized accounts, and report suspected unauthorized access promptly to the Company administrator.'] },
      { id: 'children-changes', title: 'Updates and contact', paragraphs: ['This business application is intended for authorized workforce use, not for children. The Company may update this policy when the service or its data handling changes; the in-app “Last updated” date identifies the current version. For questions or privacy requests, contact alaminkhan.xiaomi@gmail.com.'] },
      { id: 'law', title: 'Saudi privacy-law references', paragraphs: ['This policy is intended to describe the application’s current behavior and does not replace legal advice or the Company’s responsibilities under applicable law. See the official Saudi Personal Data Protection Law and the Regulation on Personal Data Transfer Outside the Kingdom for the legal framework.'], links: [
        { href: 'https://sdaia.gov.sa/en/SDAIA/about/Documents/Personal%20Data%20English%20V2-23April2023-%20Reviewed-.pdf', label: 'Saudi Personal Data Protection Law (official English text)' },
        { href: 'https://sdaia.gov.sa/en/SDAIA/about/ArchivesRegulationsAndPolicies/RegulationonPersonalDataTransferoutsideKingdomEN.pdf', label: 'Regulation on Personal Data Transfer Outside the Kingdom (official English text)' },
      ] },
    ],
  },
  ar: {
    title: 'سياسة الخصوصية',
    subtitle: 'توضح هذه السياسة كيفية تعامل مؤسسة سعد فريح للنقل مع البيانات الشخصية والتشغيلية في مدير الأسطول.',
    updatedLabel: 'تاريخ النفاذ',
    contentsLabel: 'أقسام السياسة',
    sections: [
      { id: 'controller', title: 'الجهة المشغّلة للخدمة', paragraphs: ['تُشغّل الخدمة لصالح مؤسسة سعد فريح للنقل («الشركة» أو «نحن»). تُدار بيانات الشركة الظاهرة في التطبيق من صفحة الإعدادات. لطلبات الخصوصية أو الاستفسارات، تواصل عبر alaminkhan.xiaomi@gmail.com أو مع مسؤول الشركة.'] },
      { id: 'scope', title: 'النطاق والتطبيق', paragraphs: ['تغطي هذه السياسة تطبيق مدير الأسطول على الويب وواجهاته البرمجية والدخول إلى الحساب والسجلات التشغيلية والتقارير وميزات Excel وOneDrive المتصلة. تعمل الشركة جهة تحكم في البيانات التي تدخلها أو تديرها في الخدمة. وتعالج Microsoft OneDrive ومزودو البريد والاستضافة وقاعدة البيانات والتحليلات البيانات وفق شروطهم عند انطباقها.'] },
      { id: 'information', title: 'البيانات التي يتعامل معها التطبيق', bullets: ['بيانات الحساب: الاسم والبريد الإلكتروني وتجزئة كلمة المرور والهاتف والقسم والمسمى الوظيفي والنبذة وصورة الملف الشخصي والدور والصلاحيات وحالة الموافقة والتحقق وبيانات استعادة الحساب أو التحقق منه.', 'سجلات الأسطول والورشة والمشتريات: معرّفات الشاحنات والمقطورات وأرقام الهياكل والسائقون والعدادات والحالات وسجل الصيانة وتغييرات الزيت وحركات إخراج الإطارات وكمياتها وأرقامها التسلسلية والفنيون وتفاصيل أوامر العمل وأسماء الموردين وبيانات الاتصال وأرقام الفواتير وتواريخها وفئات المصروفات والمبالغ والضريبة وقيود حسابات الأسطول والموردين والملاحظات والتكاليف والمرفقات أو التوقيعات عند تقديمها والتقارير الناتجة.', 'طلبات شراء مساحة العمل: اسم الشركة ورمز مساحة العمل واسم المسؤول وبريده الإلكتروني ورقم هاتف اختياري والخطة والمبلغ المرجعي ورقم تحويل مصرفي فريد ووقت/نسخة الموافقة على الاتفاقية وحالة المراجعة وتفاصيل مراجعة المسؤول. لا ترسل بيانات الدخول المصرفي أو بيانات البطاقة؛ فالتطبيق لا يجمعها.', 'بيانات الأمن والتدقيق: سجل الدخول والنشاط والتدقيق والإجراءات وتغييرات السجلات وعنوان IP وبيانات المتصفح ونظام التشغيل ونوع الجهاز والموقع التقريبي المستنتج من عنوان IP عند توفره.', 'بيانات المصنف المتصل: البريد الإلكتروني لحساب Microsoft ورمز تحديث OneDrive المشفّر على الخادم ومعرّفات المصنف وروابطه وحالة المزامنة وتغييرات Excel المعلقة.', 'بيانات الاستخدام والأداء: قياسات الصفحات والتفاعل عبر Vercel Analytics وSpeed Insights وMicrosoft Clarity. يعرّف تكامل Clarity الحالي الجلسات التي سجّل المستخدم الدخول فيها بمعرّف المستخدم في التطبيق، ويرسل الدور والبريد الإلكتروني والاسم كبيانات وصفية للجلسة. لا يتوفر حالياً خيار لإيقاف التحليلات من داخل التطبيق.', 'المعلومات التي ترسلها للدعم وبيانات التسليم اللازمة للتحقق من الحساب واستعادة كلمة المرور ورسائل التنبيه المفعّلة.'] },
      { id: 'purposes', title: 'أغراض استخدام البيانات', bullets: ['إنشاء الحسابات وتأمينها والتحقق من المستخدمين وتطبيق صلاحيات الأدوار والمستخدمين والموافقة على الوصول واستعادة الحسابات.', 'استلام طلبات شراء مساحات العمل ومراجعتها ومطابقة التحويلات المصرفية يدوياً باستخدام مراجعها وإنشاء مساحات العمل المعتمدة وإتاحة حساب المسؤول وحفظ سجلات الدفع والشراء.', 'إدارة أصول الأسطول وسجل الخدمة وأوامر العمل وسجلات الإطارات والزيت وفواتير الموردين وحسابات مصروف المركبات وضريبة المدخلات والتقارير ومزامنة Excel التي تطلبها الشركة.', 'عرض إشعارات الصيانة داخل التطبيق وإرسال رسائل التشغيل المهيأة والتحقيق في الأخطاء وحفظ سجلات التدقيق ومساعدة المستخدمين.', 'مراقبة موثوقية التطبيق وأدائه واستخدامه وتحسين الخدمة.'] },
      { id: 'sharing', title: 'متى تتم مشاركة البيانات', paragraphs: ['يمكن للمستخدمين المخولين الاطلاع على السجلات والتصرف فيها بحسب أدوارهم وصلاحياتهم الفردية. تتاح تفاصيل طلب شراء مساحة العمل للمسؤول الرئيسي لمراجعة الدفع وإعداد مساحة العمل. يتلقى مزودو الخدمة البيانات اللازمة للاستضافة والتشغيل والأمن والتحليل والتسليم: Vercel للاستضافة والقياسات، وNeon لقاعدة PostgreSQL، وMicrosoft لخدمات OneDrive وGraph وClarity، وResend للبريد، وip-api.com للاستدلال على الموقع التقريبي من عنوان IP ضمن تتبع النشاط. وقد تكشف الشركة البيانات إذا أوجب القانون ذلك أو لحماية الخدمة ومستخدميها. لا يُشغّل التطبيق كوسيط لبيع البيانات.'] },
      { id: 'public-links', title: 'روابط مشاركة أوامر العمل والتصدير', paragraphs: ['رابط مشاركة أمر العمل هو رابط حامل؛ يمكن لأي شخص يحصل عليه عرض أمر العمل دون تسجيل الدخول. وقد يعرض رقم الأمر وبيانات الشاحنة أو المقطورة ورقم الهيكل أو اللوحة واسم السائق والفني ووصف العمل وقائمة الفحص والملاحظات والتوقيعات المحفوظة في الأمر. شاركه مع المستلمين المقصودين فقط. قد تحتوي ملفات PDF والتقارير والمصنفات المنزلة على أنواع مماثلة من بيانات العمل أو البيانات الشخصية؛ فاحفظها وأرسلها بحذر.'] },
      { id: 'onedrive', title: 'مزامنة OneDrive والمصنف', paragraphs: ['عند توصيل OneDrive، يمنح المستخدم التطبيق صلاحية Microsoft Graph المفوضة لملفات الحساب المحدد لأغراض تكامل المصنف. يقرأ التطبيق مصنف الأسطول ويحدّثه، ويحفظ رمز التحديث مشفراً على الخادم. تُعرض تعديلات المصنف للمراجعة والتحقق من الصلاحيات قبل تغيير سجلات التطبيق؛ وقد تُكتب بيانات التطبيق في المصنف المتصل. تخضع بيانات حساب Microsoft وملفاته أيضاً لشروط Microsoft ومعلومات الخصوصية الخاصة بها.'] },
      { id: 'transfers', title: 'التخزين والمعالجة خارج المملكة', paragraphs: ['يستخدم مدير الأسطول قاعدة بيانات PostgreSQL وخدمات سحابية خارجية. اتصال قاعدة بيانات الإنتاج الحالي مهيأ لمنطقة شرق الولايات المتحدة؛ وقد يعالج مزودو الخدمة البيانات في مواقع أخرى بحسب بنيتهم التحتية وحساب Microsoft المتصل. لذلك قد تُعالج البيانات خارج المملكة العربية السعودية. وتتحمل الشركة مسؤولية تطبيق الضمانات ومتطلبات النقل المنطبقة بموجب نظام حماية البيانات الشخصية ولائحة نقل البيانات إلى خارج المملكة.'] },
      { id: 'retention', title: 'الاحتفاظ والحذف', paragraphs: ['تحتفظ الشركة بالبيانات ما دامت لازمة لتشغيل الحسابات والاحتفاظ بتاريخ الأسطول والورشة والوفاء بالالتزامات التجارية والقانونية وحماية الخدمة وتسوية النزاعات. تُحذف بعض السجلات حذفاً منطقياً أو تبقى في سجل التدقيق، وقد تستمر النسخ الاحتياطية حتى انتهاء دورة النسخ المعمول بها. لا يحدد التطبيق مدة موحدة منشورة لكل نوع من السجلات. تواصل مع الشركة لطلب المراجعة أو التصحيح أو الحذف؛ وقد تحد الالتزامات النظامية ومتطلبات سجلات التشغيل من الحذف.'] },
      { id: 'choices', title: 'خياراتك وطلبات الخصوصية', paragraphs: ['يمكنك تصحيح بيانات الملف الشخصي المتاحة في حسابك وطلب الوصول إلى بياناتك الشخصية أو الحصول عليها أو تصحيحها أو استكمالها أو تحديثها أو إتلافها، أو معالجة ما يتعلق بالموافقة عندما تكون هي الأساس المنطبق. تُدرس الطلبات بعد التحقق من الهوية وبما يخضع للقانون واستثناءاته. تواصل عبر alaminkhan.xiaomi@gmail.com أو مع مسؤول الشركة، وحدد الحساب والطلب؛ ولا ترسل كلمة المرور أو رمز الوصول.'] },
      { id: 'security', title: 'الأمن', paragraphs: ['يستخدم التطبيق المصادقة والتحقق من الصلاحيات بحسب الدور وسجلات التدقيق والتخزين المشفر لرمز تحديث OneDrive. تُخزن كلمات المرور بصيغة تجزئة. لا يمكن لأي خدمة عبر الإنترنت ضمان أمن مطلق. حافظ على سرية بيانات الدخول واستخدم الحسابات المخولة وأبلغ مسؤول الشركة فور الاشتباه بوصول غير مصرح به.'] },
      { id: 'children-changes', title: 'التحديثات والتواصل', paragraphs: ['هذا التطبيق مخصص للاستخدام الوظيفي المصرح به وليس للأطفال. قد تحدّث الشركة السياسة عند تغيير الخدمة أو طريقة التعامل مع البيانات؛ ويحدد تاريخ «آخر تحديث» داخل التطبيق النسخة الحالية. للاستفسارات أو طلبات الخصوصية، تواصل عبر alaminkhan.xiaomi@gmail.com.'] },
      { id: 'law', title: 'مراجع نظام الخصوصية السعودي', paragraphs: ['تهدف هذه السياسة إلى وصف السلوك الحالي للتطبيق، ولا تحل محل المشورة القانونية أو مسؤوليات الشركة بموجب القانون المعمول به. راجع نظام حماية البيانات الشخصية السعودي الرسمي ولائحة نقل البيانات الشخصية إلى خارج المملكة للاطلاع على الإطار النظامي.'], links: [
        { href: 'https://sdaia.gov.sa/en/SDAIA/about/Documents/Personal%20Data%20English%20V2-23April2023-%20Reviewed-.pdf', label: 'نظام حماية البيانات الشخصية (النص الإنجليزي الرسمي)' },
        { href: 'https://sdaia.gov.sa/en/SDAIA/about/ArchivesRegulationsAndPolicies/RegulationonPersonalDataTransferoutsideKingdomEN.pdf', label: 'لائحة نقل البيانات الشخصية إلى خارج المملكة (النص الإنجليزي الرسمي)' },
      ] },
    ],
  },
}

export const userAgreement: { en: DocumentCopy; ar: DocumentCopy } = {
  en: {
    title: 'Fleet Manager user agreement',
    subtitle: 'Terms for workspace customers and authorized staff who access the fleet and workshop management application.',
    updatedLabel: 'Effective date',
    contentsLabel: 'Agreement sections',
    sections: [
      { id: 'operator', title: '1. Operator and acceptance', paragraphs: ['This agreement governs authorized use of Fleet Manager for Saadfreeh Transport Est. (the “Company”). By accessing or using the application, you agree to follow these terms, the Company’s instructions, and the Privacy Policy. If you do not agree, stop using the application and contact the Company administrator.'] },
      { id: 'accounts', title: '2. Accounts and access', bullets: ['Use only an account issued or approved for you. Keep passwords and one-time codes confidential and notify the administrator if you suspect misuse.', 'You are responsible for activity performed through your account. Do not share an account or attempt to bypass a page, role, or record permission.', 'Access is limited by your role and any individual permissions. The Company may approve, restrict, suspend, reactivate, or remove accounts and permissions.'] },
      { id: 'use', title: '3. Permitted use and user duties', bullets: ['Use the application only for legitimate Company fleet, workshop, safety, reporting, and administrative work.', 'Enter accurate, complete, current information to the best of your knowledge. Correct mistakes promptly and do not create misleading vehicle, maintenance, tire, or oil records.', 'Do not upload unlawful, harmful, malicious, or unrelated content; do not probe, disrupt, reverse engineer, or attempt unauthorized access to the application or its data.', 'Handle personal data, customer details, signatures, reports, exported files, and share links only as needed for your assigned work.'] },
      { id: 'records', title: '4. Company records and reports', paragraphs: ['Operational information entered or generated for Company work remains subject to the Company’s policies and recordkeeping requirements. Reports and exports reflect the underlying data and filters at the time they are produced; check the selected dates, vehicles, quantities, and matching-record count before relying on or sharing a report. Keep exported PDFs, spreadsheets, and logs secure.'] },
      { id: 'safety', title: '5. Maintenance and safety decisions', paragraphs: ['The application helps record and organize fleet information. It does not inspect a vehicle, diagnose a defect, certify roadworthiness, or replace manufacturer guidance, qualified mechanic judgment, or required safety checks. Users and the Company remain responsible for verifying records and making maintenance, dispatch, and safety decisions. Alerts can be delayed or unavailable and must not be treated as emergency warnings.'] },
      { id: 'excel', title: '6. OneDrive and Excel integration', paragraphs: ['An administrator may connect an authorized Microsoft OneDrive account. Users must follow the Company’s access rules for that account and workbook. Workbook additions and edits enter the Excel Changes review queue; they affect app records only after a permitted user applies them and server validation succeeds. Conflicts and invalid rows need review. Deleting a worksheet row does not delete an app record. App changes may be written to the connected workbook.'] },
      { id: 'job-cards', title: '7. Job-card sharing', paragraphs: ['A job-card share link grants read access to the card to anyone who has the link. Do not publish the link or send it to an unintended recipient. A link may reveal vehicle identifiers, driver or technician names, work descriptions, notes, and signatures recorded on the card. The Company may change or disable access to the application or a shared record when needed.'] },
      { id: 'availability', title: '8. Service availability and data', paragraphs: ['The Company and its service providers may maintain, update, restrict, or temporarily interrupt the application. The app depends on network, hosting, database, email, and Microsoft services; synchronization and notification delivery are not guaranteed to be instantaneous or uninterrupted. Do not use the application as the sole copy of critical operational records. Follow Company backup and retention procedures.'] },
      { id: 'ownership', title: '9. Software and intellectual property', paragraphs: ['The application, its interface, software, design, and marks are owned by or licensed to the Company or their respective rights holders. This agreement gives you a limited, revocable right to use the service for assigned Company work; it does not transfer ownership of the software or grant permission to reuse it outside that work.'] },
      { id: 'suspension', title: '10. Suspension and ending access', paragraphs: ['The Company may suspend or end access when an account is no longer authorized, these terms or Company policy are breached, security requires it, or the service is discontinued. On request, stop using the account and return or securely delete Company exports in your possession, subject to Company instructions and applicable law.'] },
      { id: 'limits', title: '11. Important limits', paragraphs: ['The application is provided as an operational recordkeeping tool. To the extent permitted by applicable law, the Company does not promise that every record is error-free or that the service will always be available. Nothing in this agreement removes rights or liabilities that cannot lawfully be excluded.'] },
      { id: 'changes', title: '12. Changes, governing law, and contact', paragraphs: ['The Company may update these terms as the service or its operating requirements change. Continued use after an update means you are using the current version, subject to any notice or acceptance requirement imposed by applicable law. The agreement is governed by the laws of the Kingdom of Saudi Arabia, subject to mandatory rules that apply. For questions, contact the Company administrator or alaminkhan.xiaomi@gmail.com.'] },
      { id: 'bank-transfer', title: '13. Workspace purchases and bank transfers', paragraphs: ['A workspace purchase request is not a payment and does not reserve or activate a workspace. The customer must transfer the stated amount to the displayed bank account and include the unique reference. Access and database provisioning begin only after the Company confirms that the funds have arrived. The Company does not receive card or bank login credentials through the app. Bank-transfer plans do not renew automatically; each renewal requires a new transfer and manual confirmation. Contact the Company administrator about a payment mismatch or refund request.'] },
    ],
  },
  ar: {
    title: 'اتفاقية مستخدم مدير الأسطول',
    subtitle: 'شروط شراء مساحة العمل والاستخدام المصرح به لتطبيق إدارة الأسطول والورشة.',
    updatedLabel: 'تاريخ النفاذ',
    contentsLabel: 'أقسام الاتفاقية',
    sections: [
      { id: 'operator', title: '1. المشغّل والموافقة', paragraphs: ['تحكم هذه الاتفاقية الاستخدام المصرح به لتطبيق مدير الأسطول لصالح مؤسسة سعد فريح للنقل («الشركة»). بدخولك إلى التطبيق أو استخدامه، توافق على اتباع هذه الشروط وتعليمات الشركة وسياسة الخصوصية. إذا لم توافق، فتوقف عن استخدام التطبيق وتواصل مع مسؤول الشركة.'] },
      { id: 'accounts', title: '2. الحسابات والوصول', bullets: ['استخدم حساباً صادراً لك أو معتمداً من الشركة فقط. حافظ على سرية كلمات المرور ورموز الدخول لمرة واحدة وأبلغ المسؤول إذا اشتبهت في إساءة الاستخدام.', 'أنت مسؤول عن النشاط الذي يجري عبر حسابك. لا تشارك الحساب ولا تحاول تجاوز صلاحيات صفحة أو دور أو سجل.', 'يقتصر الوصول على دورك وأي صلاحيات فردية. يجوز للشركة اعتماد الحسابات أو تقييدها أو تعليقها أو إعادة تفعيلها أو إزالتها والصلاحيات المرتبطة بها.'] },
      { id: 'use', title: '3. الاستخدام المسموح ومسؤوليات المستخدم', bullets: ['استخدم التطبيق لأعمال الشركة المشروعة المتعلقة بالأسطول والورشة والسلامة والتقارير والإدارة فقط.', 'أدخل معلومات دقيقة وكاملة وحديثة حسب علمك. صحح الأخطاء فوراً ولا تنشئ سجلات مضللة للمركبات أو الصيانة أو الإطارات أو الزيت.', 'لا ترفع محتوى مخالفاً أو ضاراً أو خبيثاً أو غير ذي صلة، ولا تفحص التطبيق أو تعطلّه أو تحاول الهندسة العكسية أو الوصول غير المصرح به إلى التطبيق أو بياناته.', 'تعامل مع البيانات الشخصية وبيانات العملاء والتوقيعات والتقارير والملفات المصدرة وروابط المشاركة بالقدر اللازم لمهامك فقط.'] },
      { id: 'records', title: '4. سجلات الشركة والتقارير', paragraphs: ['تظل المعلومات التشغيلية المدخلة أو الناتجة عن عمل الشركة خاضعة لسياسات الشركة ومتطلبات حفظ السجلات. تعكس التقارير والصادرات البيانات والفلاتر وقت إنشائها؛ تحقق من التواريخ والمركبات والكميات وعدد السجلات المطابقة قبل الاعتماد على التقرير أو مشاركته. احفظ ملفات PDF وجداول البيانات والسجلات المصدرة بأمان.'] },
      { id: 'safety', title: '5. قرارات الصيانة والسلامة', paragraphs: ['يساعد التطبيق في تسجيل معلومات الأسطول وتنظيمها. لا يفحص التطبيق المركبة ولا يشخص العيوب ولا يعتمد صلاحيتها للسير ولا يحل محل إرشادات الشركة المصنعة أو تقدير الفني المؤهل أو فحوص السلامة المطلوبة. تظل مسؤولية التحقق من السجلات واتخاذ قرارات الصيانة والتشغيل والسلامة على المستخدمين والشركة. قد تتأخر التنبيهات أو تتعطل، ولا يجوز اعتبارها تحذيرات طوارئ.'] },
      { id: 'excel', title: '6. تكامل OneDrive وExcel', paragraphs: ['قد يربط المسؤول حساب Microsoft OneDrive معتمداً. يجب على المستخدمين اتباع قواعد الشركة للوصول إلى الحساب والمصنف. تدخل الإضافات والتعديلات في المصنف إلى قائمة مراجعة تغييرات Excel؛ ولا تؤثر في سجلات التطبيق إلا بعد تطبيقها من مستخدم مخول ونجاح التحقق على الخادم. تتطلب التعارضات والصفوف غير الصحيحة المراجعة. لا يؤدي حذف صف من ورقة العمل إلى حذف سجل التطبيق. وقد تُكتب تغييرات التطبيق إلى المصنف المتصل.'] },
      { id: 'job-cards', title: '7. مشاركة أوامر العمل', paragraphs: ['يمنح رابط مشاركة أمر العمل حق قراءة الأمر لكل من لديه الرابط. لا تنشر الرابط ولا ترسله إلى شخص غير مقصود. قد يكشف الرابط معرّفات المركبة وأسماء السائق أو الفني ووصف العمل والملاحظات والتوقيعات المسجلة في الأمر. يجوز للشركة تغيير أو تعطيل الوصول إلى التطبيق أو سجل مشترك عند الحاجة.'] },
      { id: 'availability', title: '8. توفر الخدمة والبيانات', paragraphs: ['يجوز للشركة ومزودي الخدمة صيانة التطبيق أو تحديثه أو تقييد الوصول إليه أو إيقافه مؤقتاً. يعتمد التطبيق على الشبكة والاستضافة وقاعدة البيانات والبريد وخدمات Microsoft؛ ولا يُضمن أن تتم المزامنة أو تسليم الإشعارات فوراً أو دون انقطاع. لا تعتمد على التطبيق بوصفه النسخة الوحيدة من السجلات التشغيلية المهمة. اتبع إجراءات النسخ الاحتياطي والاحتفاظ الخاصة بالشركة.'] },
      { id: 'ownership', title: '9. البرمجيات والملكية الفكرية', paragraphs: ['تملك الشركة أو أصحاب الحقوق المعنيون التطبيق وواجهته وبرمجياته وتصميمه وعلاماته أو يملكون ترخيصها. تمنحك هذه الاتفاقية حقاً محدوداً وقابلاً للإلغاء لاستخدام الخدمة في مهام الشركة الموكلة إليك؛ ولا تنقل ملكية البرمجيات أو تمنح حق استخدامها خارج تلك المهام.'] },
      { id: 'suspension', title: '10. تعليق الوصول وإنهاؤه', paragraphs: ['يجوز للشركة تعليق الوصول أو إنهاؤه عندما يصبح الحساب غير مخول أو عند مخالفة هذه الشروط أو سياسات الشركة أو لمتطلبات الأمن أو عند إيقاف الخدمة. عند الطلب، توقف عن استخدام الحساب وأعد أو احذف بأمان صادرات الشركة الموجودة لديك، وفق تعليمات الشركة والقانون المعمول به.'] },
      { id: 'limits', title: '11. حدود مهمة', paragraphs: ['يُقدم التطبيق كأداة لتسجيل العمليات. وبالقدر الذي يسمح به القانون، لا تضمن الشركة خلو كل سجل من الأخطاء أو توفر الخدمة دائماً. لا ينتقص أي بند في هذه الاتفاقية من الحقوق أو المسؤوليات التي لا يجوز استبعادها قانوناً.'] },
      { id: 'changes', title: '12. التعديلات والقانون والتواصل', paragraphs: ['يجوز للشركة تحديث الشروط عند تغير الخدمة أو متطلباتها التشغيلية. ويعني الاستمرار في الاستخدام بعد التحديث استخدام النسخة الحالية، مع مراعاة أي متطلب للإشعار أو القبول يفرضه القانون المعمول به. تخضع الاتفاقية لأنظمة المملكة العربية السعودية، مع مراعاة القواعد الإلزامية المنطبقة. للاستفسار، تواصل مع مسؤول الشركة أو عبر alaminkhan.xiaomi@gmail.com.'] },
      { id: 'bank-transfer', title: '13. شراء مساحة العمل والتحويل المصرفي', paragraphs: ['طلب شراء مساحة العمل ليس دفعة ولا يحجز مساحة العمل أو يفعّلها. يجب على العميل تحويل المبلغ الموضح إلى الحساب المصرفي الظاهر وإضافة المرجع الفريد. يبدأ إتاحة الوصول وإعداد قاعدة البيانات فقط بعد تأكيد الشركة وصول المبلغ. لا يتلقى التطبيق بيانات الدخول المصرفي أو بيانات البطاقة. لا تتجدد خطط التحويل المصرفي تلقائياً؛ ويتطلب كل تجديد تحويلاً جديداً وتأكيداً يدوياً. تواصل مع مسؤول الشركة بشأن اختلاف الدفع أو طلب الاسترداد.'] },
    ],
  },
}
